parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "recommendation": {
      "type": "string",
      "enum": [
        "dispatch_vendor",
        "already_dispatched",
        "needs_human"
      ],
      "description": "What should happen with this ticket."
    },
    "emergency": {
      "type": "boolean",
      "description": "The ticket suggests gas, fire, flooding, no heat in freezing weather, electrical sparking or another emergency."
    },
    "trade": {
      "type": "string",
      "enum": [
        "plumbing",
        "electrical",
        "hvac",
        "appliance",
        "locksmith",
        "pest_control",
        "roofing",
        "general_maintenance"
      ],
      "description": "Trade the job needs."
    },
    "priority": {
      "type": "string",
      "enum": [
        "routine",
        "urgent"
      ],
      "description": "Urgent when the problem is getting worse or blocks normal use of the unit, but is not an emergency."
    },
    "vendor_id": {
      "type": [
        "string",
        "null"
      ],
      "description": "Vendor to dispatch, or null."
    },
    "labor_hours": {
      "type": "number",
      "description": "Estimated labor hours. 0 if not dispatching."
    },
    "materials_cost": {
      "type": "number",
      "description": "Estimated materials cost. 0 if not dispatching."
    },
    "estimated_total": {
      "type": "number",
      "description": "labor_hours x hourly rate + materials_cost + trip charge. 0 if not dispatching."
    },
    "not_to_exceed": {
      "type": "number",
      "description": "Cap for the work order. At least the estimate, never above the property not-to-exceed amount. 0 if not dispatching."
    },
    "scope_of_work": {
      "type": "string",
      "description": "What the vendor needs to know: the problem, where in the unit, access notes. Empty if not dispatching."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "recommendation",
    "emergency",
    "trade",
    "priority",
    "vendor_id",
    "labor_hours",
    "materials_cost",
    "estimated_total",
    "not_to_exceed",
    "scope_of_work",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Maintenance dispatch agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize ticket'); // one(): defined by guardPreamble; survives a lost item link
const findEmergency = (text, cfg, outdoorF, unknownTempIsCold) => {
  const t = ' ' + String(text ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ') + ' ';
  const has = (k) => t.includes(' ' + String(k).toLowerCase() + ' ');
  const hits = (cfg.emergency_terms ?? []).filter(has);
  const noHeat = (cfg.no_heat_terms ?? []).some(has);
  const tempKnown = typeof outdoorF === 'number' && Number.isFinite(outdoorF);
  const cold = tempKnown ? outdoorF <= cfg.no_heat_emergency_below_f : (unknownTempIsCold || has('freezing') || has('frozen'));
  if (noHeat && cold) hits.push(tempKnown ? 'no heat at ' + outdoorF + 'F outside' : 'no heat in freezing weather');
  return hits;
};
const TRADE_LABELS = {"plumbing":"plumbing","electrical":"electrical","hvac":"heating and cooling","appliance":"appliance repair","locksmith":"lock and key","pest_control":"pest control","roofing":"roofing","general_maintenance":"general maintenance"};
const ctx = $json; // fresh read: { ticket, vendor, property, open_work_orders }
const t = ctx.ticket ?? {};
const v = ctx.vendor ?? null;
const p = ctx.property ?? {};
const openWos = ctx.open_work_orders ?? [];
const rec = out?.recommendation;
const round2 = (n) => Math.round(n * 100) / 100;

// 1. Emergencies stop here, whatever the agent said. Unknown outdoor temperature counts as cold.
const outdoor = p.outdoor_temp_f == null ? null : Number(p.outdoor_temp_f);
const found = findEmergency((t.title ?? req.title) + ' ' + (t.description ?? req.description), cfg, outdoor, outdoor === null);
const emergencyTerms = [...new Set([...(req.emergency_terms ?? []), ...found, ...(out?.emergency ? ['agent flagged an emergency'] : [])])];
const emergency = emergencyTerms.length > 0;
if (emergency) reasons.push('possible emergency (' + emergencyTerms.join(', ') + '): call the tenant and handle it now, not through a routine dispatch');

// 2. The ticket itself.
if (!t.ticket_id) reasons.push('ticket ' + req.ticket_id + ' not found on re-read');
if (t.status && !['new', 'open', 'triaged'].includes(t.status)) reasons.push('ticket status is now ' + t.status);
if (rec === 'needs_human' && !emergency) reasons.push('agent asks for a person: ' + (out?.questions_for_human ?? []).join('; '));
const noop = rec === 'already_dispatched' && openWos.length > 0;
if (rec === 'already_dispatched' && !openWos.length) reasons.push('agent says already dispatched but the ticket has no open work order');

// 3. The dispatch: vendor, insurance, price.
let estimate = null;
if (rec === 'dispatch_vendor') {
  if (openWos.length) reasons.push('ticket already has open work order ' + openWos.map((w) => w.work_order_id).join(', '));
  if (!TRADE_LABELS[out.trade]) reasons.push('unknown trade ' + out.trade);
  if (!v || (out.vendor_id && v.vendor_id !== out.vendor_id)) reasons.push('vendor ' + out.vendor_id + ' not found on re-read');
  else {
    if (v.status !== 'approved') reasons.push('vendor ' + v.vendor_id + ' status is ' + v.status + ', not approved');
    if (!(v.approved_trades ?? []).includes(out.trade)) reasons.push('vendor ' + v.vendor_id + ' is not approved for ' + out.trade + ' (approved for ' + ((v.approved_trades ?? []).join(', ') || 'nothing') + ')');
    const coi = String(v.coi_expires_on ?? '').slice(0, 10);
    const validThrough = new Date(Date.now() + cfg.coi_min_days_valid * 86400000).toISOString().slice(0, 10);
    if (!coi) reasons.push('vendor ' + v.vendor_id + ' has no certificate of insurance on file');
    else if (coi < validThrough) reasons.push('vendor ' + v.vendor_id + ' certificate of insurance expires ' + coi + ', needs to be valid through ' + validThrough);
    const rate = Number(v.hourly_rate);
    if (!Number.isFinite(rate)) reasons.push('vendor ' + v.vendor_id + ' has no hourly rate on file, so the estimate cannot be checked');
    else {
      estimate = round2(Number(out.labor_hours) * rate + Number(out.materials_cost) + Number(v.trip_charge ?? 0));
      if (Math.abs(estimate - Number(out.estimated_total)) > 0.01) reasons.push('agent estimate ' + out.estimated_total + ' differs from recomputed ' + estimate + ' (' + out.labor_hours + ' h x ' + rate + ' + materials ' + out.materials_cost + ' + trip ' + (v.trip_charge ?? 0) + ')');
    }
  }
  const nte = Number(p.nte_limit);
  if (!(nte > 0)) reasons.push('no not-to-exceed amount on file for property ' + req.property_id);
  else {
    if (Number(out.not_to_exceed) > nte) reasons.push('work order cap ' + out.not_to_exceed + ' is above the property not-to-exceed ' + nte);
    if (estimate !== null && estimate > nte) reasons.push('recomputed estimate ' + estimate + ' is above the property not-to-exceed ' + nte);
  }
  if (estimate !== null && Number(out.not_to_exceed) < estimate) reasons.push('work order cap ' + out.not_to_exceed + ' is below the estimate ' + estimate);
  if (!String(out.scope_of_work ?? '').trim()) reasons.push('no scope of work for the vendor');
  if (!t.tenant_email) reasons.push('no tenant email on file for the update');
}

const action = {
  type: rec === 'dispatch_vendor' ? 'dispatch_vendor' : 'none',
  emergency,
  ticket_id: req.ticket_id,
  property_id: req.property_id,
  unit_id: req.unit_id,
  vendor_id: v?.vendor_id ?? out?.vendor_id ?? null,
  vendor_name: v?.name ?? null,
  trade: out?.trade ?? null,
  trade_label: TRADE_LABELS[out?.trade] ?? null,
  priority: out?.priority ?? 'routine',
  scope_of_work: out?.scope_of_work ?? '',
  estimate,
  not_to_exceed: Number(out?.not_to_exceed ?? 0),
  // Tenant contact comes from the system of record, never from the ticket text or the model.
  tenant_email: t.tenant_email ?? null,
  tenant_first_name: t.tenant_first_name ?? null,
};
const summary = 'Ticket ' + req.ticket_id + ' · property ' + req.property_id + ' unit ' + (req.unit_id || 'common area') + '\n'
  + 'Proposed: *' + action.type + '*' + (action.type === 'dispatch_vendor' ? ' to ' + (action.vendor_name ?? action.vendor_id) + ' for ' + action.trade + ' (' + action.priority + '), estimate ' + estimate + ', cap ' + action.not_to_exceed + ' (property limit ' + p.nte_limit + ')' : '') + '.\n'
  + 'Scope for the vendor: ' + action.scope_of_work + '\n'
  + 'The tenant gets the standard dispatch update after the work order is confirmed.\n' + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const ok = ['dispatched', 'assigned', 'scheduled'].includes($json.status)
  && $json.ticket_id === planned.ticket_id
  && $json.vendor_id === planned.vendor_id
  && Math.abs(Number($json.not_to_exceed) - Number(planned.not_to_exceed)) <= 0.01;
const detail = 'work order ' + $json.work_order_id + ' shows ' + $json.status + ' for vendor ' + $json.vendor_id + ' with cap ' + $json.not_to_exceed + ', expected ' + planned.vendor_id + ' with cap ' + planned.not_to_exceed;
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize ticket'); } catch (e) {}
try { agent = one('Maintenance dispatch agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = (intake.emergency_terms?.length || guard?.action?.emergency ? ':rotating_light: POSSIBLE EMERGENCY, handle now · ' : '') + 'Ticket ' + intake.ticket_id + ' · property ' + intake.property_id + ' unit ' + (intake.unit_id || 'common area') + ' · proposed ' + (agent?.output?.recommendation ?? 'none');
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "property operations",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

